struct ClipVtx {
    f32 x;
    f32 y;
    f32 z;
    s16 c0;
    s16 c1;
    s16 c2;
    s16 pad;
};

void func_15185B54(struct ClipVtx *a, struct ClipVtx *b, struct ClipVtx *out) {
    f32 t;

    t = a->x / (a->x - b->x);
    out->x = 0.0f;
    out->y = a->y + (b->y - a->y) * t;
    out->z = a->z + (b->z - a->z) * t;
    out->c0 = (s16)((f32)a->c0 + (f32)(b->c0 - a->c0) * t);
    out->c1 = (s16)((f32)a->c1 + (f32)(b->c1 - a->c1) * t);
    out->c2 = (s16)((f32)a->c2 + (f32)(b->c2 - a->c2) * t);
}
